// Validation des inputs
const body = $input.first().json.body;

if (!body.mel_path && !body.mel_content) {
  throw new Error('MEL document required (mel_path or mel_content)');
}

if (!body.mmel_path && !body.mmel_content) {
  throw new Error('MMEL document required (mmel_path or mmel_content)');
}

// Générer un ID unique pour ce run
const runId = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14) + '_' + Math.random().toString(36).slice(2, 8);

return {
  runId,
  melSource: body.mel_path || 'inline_content',
  mmelSource: body.mmel_path || 'inline_content',
  melContent: body.mel_content || null,
  mmelContent: body.mmel_content || null,
  apiKey: body.api_key || $env.MISTRAL_API_KEY,
  options: {
    semanticMatching: body.semantic_matching !== false,
    llmAnalysis: body.llm_analysis !== false,
    confidenceThreshold: body.confidence_threshold || 0.85
  }
};

