parameters.jsCode:
// Indexation et Matching MEL ↔ MMEL
const melItems = $input.first().json.melItems;
const mmelItems = $input.first().json.mmelItems;
const melEmbeddings = $input.first().json.melEmbeddings || [];
const mmelEmbeddings = $input.first().json.mmelEmbeddings || [];

// Fonction de normalisation
function normalizeKey(ata, itemNum) {
  const normAta = (ata || '').toString().replace(/[^\d\-]/g, '').toUpperCase();
  const normItem = (itemNum || '').toString().replace(/\s+/g, '').toUpperCase();
  return `${normAta}|${normItem}`;
}

// Fonction de similarité cosinus
function cosineSimilarity(a, b) {
  if (!a || !b || a.length !== b.length) return 0;
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

// Créer l'index MMEL
const mmelIndex = {};
mmelItems.forEach((item, idx) => {
  const key = normalizeKey(item.ata_chapter, item.item_number);
  mmelIndex[key] = { ...item, embedding: mmelEmbeddings[idx] || null };
});

// Matcher chaque item MEL
const matches = [];
const matchedMmelKeys = new Set();

melItems.forEach((melItem, idx) => {
  const melKey = normalizeKey(melItem.ata_chapter, melItem.item_number);
  const melEmb = melEmbeddings[idx] || null;

  // 1. Recherche exacte
  let exactMatch = mmelIndex[melKey] || null;
  let exactScore = exactMatch ? 1.0 : 0;

  // 2. Recherche sémantique si pas de match exact et embeddings disponibles
  let semanticScore = 0;
  let semanticMatch = null;

  if (!exactMatch && melEmb) {
    let bestScore = 0;
    let bestKey = null;

    for (const [mmelKey, mmelItem] of Object.entries(mmelIndex)) {
      if (mmelItem.embedding) {
        const sim = cosineSimilarity(melEmb, mmelItem.embedding);
        if (sim > bestScore) {
          bestScore = sim;
          bestKey = mmelKey;
        }
      }
    }

    if (bestScore >= 0.85) {
      semanticMatch = mmelIndex[bestKey];
      semanticScore = bestScore;
    }
  }

  // Déterminer le match final
  const finalMatch = exactMatch || semanticMatch;
  const finalMmelKey = exactMatch ? melKey : (semanticMatch ? Object.keys(mmelIndex).find(k => mmelIndex[k] === semanticMatch) : null);

  if (finalMmelKey) {
    matchedMmelKeys.add(finalMmelKey);
  }

  matches.push({
    mel_item_id: melKey,
    mmel_item_id: finalMmelKey,
    exact_match: !!exactMatch,
    exact_score: exactScore,
    semantic_score: semanticScore,
    combined_score: exactMatch ? 1.0 : semanticScore * 0.4,
    match_type: exactMatch ? 'exact' : (semanticMatch ? 'semantic' : 'none'),
    match_confidence: exactMatch ? 'high' : (semanticScore >= 0.95 ? 'high' : (semanticScore >= 0.85 ? 'medium' : 'low')),
    requires_hitl_review: !exactMatch && semanticScore < 0.95,
    hitl_reason: !exactMatch ? (semanticMatch ? `Semantic match only (${(semanticScore*100).toFixed(1)}%)` : 'No matching MMEL item found') : ''
  });
});

// Identifier les items MMEL non matchés
const unmatchedMmel = Object.keys(mmelIndex).filter(k => !matchedMmelKeys.has(k));

return {
  melItems,
  mmelItems,
  matches,
  unmatchedMmel,
  stats: {
    totalMel: melItems.length,
    totalMmel: mmelItems.length,
    matched: matches.filter(m => m.mmel_item_id).length,
    exactMatches: matches.filter(m => m.exact_match).length,
    semanticMatches: matches.filter(m => m.match_type === 'semantic').length,
    noMatch: matches.filter(m => !m.mmel_item_id).length,
    hitlRequired: matches.filter(m => m.requires_hitl_review).length
  }
};

// Comparaison MEL ↔ MMEL et génération des verdicts
const { melItems, mmelItems, matches, unmatchedMmel } = $input.first().json;

const CATEGORY_HIERARCHY = { 'A': 1, 'B': 2, 'C': 3, 'D': 4, '-': 5, '': 5 };

const VERDICT_SEVERITY = {
  'COMPLIANT': 'info',
  'MORE_RESTRICTIVE': 'info',
  'LESS_RESTRICTIVE': 'critical',
  'MISSING_IN_MEL': 'warning',
  'MISSING_IN_MMEL': 'info',
  'CATEGORY_MISMATCH': 'high',
  'REMARKS_DEVIATION': 'medium'
};

const SLA_HOURS = {
  'critical': 48,
  'high': 48,
  'medium': 24,
  'warning': 24,
  'info': 0
};

// Créer les index
const melIndex = {};
melItems.forEach(item => {
  const key = `${item.ata_chapter}|${item.item_number}`.replace(/\s/g, '');
  melIndex[key] = item;
});

const mmelIndex = {};
mmelItems.forEach(item => {
  const key = `${item.ata_chapter}|${item.item_number}`.replace(/\s/g, '');
  mmelIndex[key] = item;
});

// Fonctions de comparaison
function compareCategories(melCat, mmelCat) {
  const melRank = CATEGORY_HIERARCHY[melCat?.toUpperCase()?.trim()] || 5;
  const mmelRank = CATEGORY_HIERARCHY[mmelCat?.toUpperCase()?.trim()] || 5;

  if (melRank === mmelRank) return { status: 'equal', notes: 'Categories match' };
  if (melRank < mmelRank) return { status: 'more_restrictive', notes: `MEL (${melCat}) more restrictive than MMEL (${mmelCat})` };
  return { status: 'less_restrictive', notes: `MEL (${melCat}) LESS restrictive than MMEL (${mmelCat}) - VIOLATION` };
}

function parseInterval(interval) {
  if (!interval) return null;
  const str = interval.toString().toLowerCase();
  const dayMatch = str.match(/(\d+)\s*d/);
  if (dayMatch) return parseInt(dayMatch[1]);
  const hourMatch = str.match(/(\d+)\s*h/);
  if (hourMatch) return parseInt(hourMatch[1]) / 24;
  return null;
}

function compareIntervals(melInt, mmelInt) {
  const melDays = parseInterval(melInt);
  const mmelDays = parseInterval(mmelInt);

  if (melDays === null || mmelDays === null) {
    if (melInt && !mmelInt) return { status: 'more_restrictive', notes: 'MEL specifies interval, MMEL does not' };
    if (mmelInt && !melInt) return { status: 'less_restrictive', notes: 'MMEL requires interval, MEL does not specify' };
    return { status: 'unknown', notes: 'Could not parse intervals' };
  }

  if (melDays === mmelDays) return { status: 'equal', notes: `Intervals match (${melDays} days)` };
  if (melDays < mmelDays) return { status: 'more_restrictive', notes: `MEL (${melDays}d) shorter than MMEL (${mmelDays}d)` };
  return { status: 'less_restrictive', notes: `MEL (${melDays}d) longer than MMEL (${mmelDays}d)` };
}

function compareRemarks(melRem, mmelRem) {
  const mel = (melRem || '').toLowerCase().trim();
  const mmel = (mmelRem || '').toLowerCase().trim();

  if (!mel && !mmel) return { status: 'equal', notes: 'No remarks in either' };
  if (mel === mmel) return { status: 'equal', notes: 'Remarks identical' };

  // Check (M) maintenance requirement
  const melHasM = mel.includes('(m)');
  const mmelHasM = mmel.includes('(m)');

  if (melHasM && !mmelHasM) return { status: 'more_restrictive', notes: 'MEL adds maintenance requirement (M)' };
  if (mmelHasM && !melHasM) return { status: 'less_restrictive', notes: 'MEL removes maintenance requirement (M)' };

  return { status: 'different', notes: 'Remarks differ - requires review' };
}

// Comparer les items
const comparisons = [];

for (const match of matches) {
  const melItem = melIndex[match.mel_item_id] || {};
  const mmelItem = match.mmel_item_id ? mmelIndex[match.mmel_item_id] : null;

  if (!mmelItem) {
    // Item MEL sans équivalent MMEL
    comparisons.push({
      mel_item_id: match.mel_item_id,
      mmel_item_id: null,
      ata_chapter: melItem.ata_chapter || '',
      item_number: melItem.item_number || '',
      item_description: melItem.item_description || '',
      verdict: 'MISSING_IN_MMEL',
      severity: 'info',
      mel_category: melItem.category || '',
      mmel_category: '',
      mel_remarks: melItem.remarks || '',
      mmel_remarks: '',
      details: [{ field: 'mmel_item', status: 'different', notes: 'Item exists in MEL but not in MMEL - operator-specific' }],
      requires_hitl_review: false,
      hitl_reason: '',
      sla_hours: 0,
      compared_at: new Date().toISOString()
    });
    continue;
  }

  // Comparer les différents champs
  const details = [];
  const verdicts = [];

  const catComp = compareCategories(melItem.category, mmelItem.category);
  details.push({ field: 'category', mel_value: melItem.category, mmel_value: mmelItem.category, ...catComp });
  verdicts.push(catComp.status);

  const intComp = compareIntervals(melItem.repair_interval, mmelItem.repair_interval);
  details.push({ field: 'repair_interval', mel_value: melItem.repair_interval, mmel_value: mmelItem.repair_interval, ...intComp });
  if (intComp.status !== 'unknown') verdicts.push(intComp.status);

  const remComp = compareRemarks(melItem.remarks, mmelItem.remarks);
  details.push({ field: 'remarks', mel_value: melItem.remarks, mmel_value: mmelItem.remarks, ...remComp });
  if (remComp.status !== 'equal') verdicts.push(remComp.status);

  // Déterminer le verdict final
  let finalVerdict;
  if (verdicts.includes('less_restrictive')) {
    finalVerdict = 'LESS_RESTRICTIVE';
  } else if (verdicts.every(v => v === 'equal')) {
    finalVerdict = 'COMPLIANT';
  } else if (verdicts.includes('more_restrictive') && !verdicts.includes('less_restrictive')) {
    finalVerdict = 'MORE_RESTRICTIVE';
  } else if (verdicts.includes('different')) {
    finalVerdict = 'REMARKS_DEVIATION';
  } else {
    finalVerdict = 'COMPLIANT';
  }

  const severity = VERDICT_SEVERITY[finalVerdict] || 'info';
  const slaHours = SLA_HOURS[severity] || 0;
  const requiresHitl = ['critical', 'high', 'medium'].includes(severity);

  comparisons.push({
    mel_item_id: match.mel_item_id,
    mmel_item_id: match.mmel_item_id,
    ata_chapter: melItem.ata_chapter || '',
    item_number: melItem.item_number || '',
    item_description: melItem.item_description || '',
    verdict: finalVerdict,
    severity,
    mel_category: melItem.category || '',
    mmel_category: mmelItem.category || '',
    mel_remarks: melItem.remarks || '',
    mmel_remarks: mmelItem.remarks || '',
    mel_repair_interval: melItem.repair_interval || '',
    mmel_repair_interval: mmelItem.repair_interval || '',
    details,
    requires_hitl_review: requiresHitl,
    hitl_reason: requiresHitl ? `${finalVerdict}: ${details.filter(d => d.status !== 'equal').map(d => d.notes).join('; ')}` : '',
    sla_hours: slaHours,
    compared_at: new Date().toISOString()
  });
}

// Ajouter les items MMEL non matchés
for (const mmelKey of unmatchedMmel) {
  const mmelItem = mmelIndex[mmelKey];
  if (!mmelItem) continue;

  comparisons.push({
    mel_item_id: '',
    mmel_item_id: mmelKey,
    ata_chapter: mmelItem.ata_chapter || '',
    item_number: mmelItem.item_number || '',
    item_description: mmelItem.item_description || '',
    verdict: 'MISSING_IN_MEL',
    severity: 'warning',
    mel_category: '',
    mmel_category: mmelItem.category || '',
    mel_remarks: '',
    mmel_remarks: mmelItem.remarks || '',
    details: [{ field: 'mel_item', status: 'different', notes: 'MMEL item not found in MEL - verify if equipment installed' }],
    requires_hitl_review: true,
    hitl_reason: 'MMEL item not found in MEL - verify if equipment installed',
    sla_hours: 48,
    compared_at: new Date().toISOString()
  });
}

// Calculer les statistiques
const stats = {
  total: comparisons.length,
  compliant: comparisons.filter(c => c.verdict === 'COMPLIANT').length,
  more_restrictive: comparisons.filter(c => c.verdict === 'MORE_RESTRICTIVE').length,
  less_restrictive: comparisons.filter(c => c.verdict === 'LESS_RESTRICTIVE').length,
  missing_in_mel: comparisons.filter(c => c.verdict === 'MISSING_IN_MEL').length,
  missing_in_mmel: comparisons.filter(c => c.verdict === 'MISSING_IN_MMEL').length,
  other_deviations: comparisons.filter(c => c.verdict === 'REMARKS_DEVIATION').length,
  hitl_required: comparisons.filter(c => c.requires_hitl_review).length
};

stats.compliance_rate = ((stats.compliant + stats.more_restrictive) / Math.max(stats.total, 1) * 100).toFixed(2);

const severityBreakdown = {
  critical: comparisons.filter(c => c.severity === 'critical').length,
  high: comparisons.filter(c => c.severity === 'high').length,
  medium: comparisons.filter(c => c.severity === 'medium').length,
  warning: comparisons.filter(c => c.severity === 'warning').length,
  info: comparisons.filter(c => c.severity === 'info').length
};

return {
  comparisons,
  summary: stats,
  severity_breakdown: severityBreakdown
};

// Génération du rapport d'audit et des logs HITL
const { comparisons, summary, severity_breakdown } = $input.first().json;
const runId = $('Validate Input').first().json.runId;

// Rapport complet
const auditReport = {
  run_id: runId,
  audit_timestamp: new Date().toISOString(),
  mel_document: $('Validate Input').first().json.melSource,
  mmel_document: $('Validate Input').first().json.mmelSource,
  summary,
  severity_breakdown,
  comparisons
};

// Extraire les findings critiques
const criticalFindings = comparisons
  .filter(c => c.severity === 'critical')
  .map(c => ({
    item: `${c.ata_chapter}-${c.item_number}`,
    description: c.item_description,
    verdict: c.verdict,
    details: c.hitl_reason,
    mel_category: c.mel_category,
    mmel_category: c.mmel_category
  }));

// Log HITL
const hitlItems = comparisons
  .filter(c => c.requires_hitl_review)
  .sort((a, b) => {
    const severityOrder = { critical: 0, high: 1, medium: 2, warning: 3, info: 4 };
    return severityOrder[a.severity] - severityOrder[b.severity];
  })
  .map(c => ({
    id: `${c.ata_chapter}-${c.item_number}`,
    verdict: c.verdict,
    severity: c.severity,
    sla_hours: c.sla_hours,
    reason: c.hitl_reason,
    mel_data: {
      item_id: c.mel_item_id,
      category: c.mel_category,
      remarks: c.mel_remarks,
      repair_interval: c.mel_repair_interval
    },
    mmel_data: {
      item_id: c.mmel_item_id,
      category: c.mmel_category,
      remarks: c.mmel_remarks,
      repair_interval: c.mmel_repair_interval
    },
    details: c.details?.filter(d => d.status !== 'equal').map(d => d.notes) || [],
    validation: {
      status: 'PENDING',
      decision: null,
      corrective_action: null,
      validated_by: null,
      validated_at: null,
      comments: null
    }
  }));

const hitlLog = {
  generated_at: new Date().toISOString(),
  run_id: runId,
  total_items_for_review: hitlItems.length,
  by_severity: {
    critical: hitlItems.filter(i => i.severity === 'critical').length,
    high: hitlItems.filter(i => i.severity === 'high').length,
    medium: hitlItems.filter(i => i.severity === 'medium').length,
    warning: hitlItems.filter(i => i.severity === 'warning').length
  },
  items: hitlItems
};

// Recommandations
const recommendations = [];
if (summary.less_restrictive > 0) {
  recommendations.push({
    priority: 'HIGH',
    action: `Review ${summary.less_restrictive} items where MEL is less restrictive than MMEL`,
    deadline: '48 hours'
  });
}
if (summary.missing_in_mel > 0) {
  recommendations.push({
    priority: 'MEDIUM',
    action: `Verify ${summary.missing_in_mel} MMEL items not found in MEL`,
    deadline: '1 week'
  });
}

// Rapport final
const finalReport = {
  run_id: runId,
  generated_at: new Date().toISOString(),
  status: 'completed',
  summary,
  severity_breakdown,
  critical_findings: criticalFindings,
  recommendations
};

return {
  auditReport,
  hitlLog,
  finalReport
};

